export const dataset={universes:[universe],continuities:[continuity],characters,series:seriesList,runs,stories:[],issues,collections,creators,relationships:[],readingPaths:[]};
export function validateDataset(){const errors=[]; const checks=[["universe",dataset.universes,validateUniverse],["continuity",dataset.continuities,validateContinuity],["character",dataset.characters,validateCharacter],["series",dataset.series,validateSeries],["run",dataset.runs,validateRun],["issue",dataset.issues,validateIssue],["collection",dataset.collections,validateCollection],["creator",dataset.creators,validateCreator]]; const ids={}; for(const [name,list,fn] of checks){ids[name]=new Set(); for(const e of list){const v=fn(e); if(!v.valid)errors.push(`[${name}/${e.id}] ${v.errors.join("; ")}`); if(ids[name].has(e.id))errors.push(`Duplicate ${name}: ${e.id}`); ids[name].add(e.id);}} for(const s of dataset.series){for(const id of s.characterIds||[])if(!ids.character.has(id))errors.push(`Series ${s.id} missing character ${id}`); for(const id of s.creatorIds||[])if(!ids.creator.has(id))errors.push(`Series ${s.id} missing creator ${id}`);} for(const r of dataset.runs){if(!ids.series.has(r.seriesId))errors.push(`Run ${r.id} missing series`);} for(const i of dataset.issues){if(!ids.series.has(i.seriesId))errors.push(`Issue ${i.id} missing series`);} for(const c of dataset.collections){for(const id of c.seriesIds||[])if(!ids.series.has(id))errors.push(`Collection ${c.id} missing series ${id}`); for(const row of c.issueCoverage||[]){if(!ids.issue.has(row.issueId))errors.push(`Collection ${c.id} missing issue ${row.issueId}`); const iss=dataset.issues.find(x=>x.id===row.issueId); if(iss&&iss.seriesId!==row.seriesId)errors.push(`Collection ${c.id} has wrong series for ${row.issueId}`);}} for(const s of dataset.series){const nums=dataset.issues.filter(i=>i.seriesId===s.id&&i.issueLabelType==="numbered"&&/^#[0-9]+$/.test(i.issueLabel)).map(i=>Number(i.issueNumber)).sort((a,b)=>a-b); const exp=Array.from({length:s.issueCount},(_,i)=>i+1); if(JSON.stringify(nums)!==JSON.stringify(exp))errors.push(`Series ${s.id}: numbered issues do not equal 1..${s.issueCount}`);} return {valid:errors.length===0,errors};}
export async function importDataset({upsertEntity,upsertCollectionEdition,COLLECTIONS}){const validation=validateDataset(); const result={validation,written:{},errors:[]}; if(!validation.valid)return result; const writeAll=async(col,list,fn=upsertEntity)=>{let n=0; for(const e of list){try{if(fn===upsertEntity)await upsertEntity(col,e.id,e);else await fn(e.id,e);n++;}catch(err){result.errors.push(`${col}/${e.id}: ${err.message}`);}}result.written[col]=n;}; await writeAll(COLLECTIONS.UNIVERSES,dataset.universes); await writeAll(COLLECTIONS.CONTINUITIES,dataset.continuities); await writeAll(COLLECTIONS.CHARACTERS,dataset.characters); await writeAll(COLLECTIONS.CREATORS,dataset.creators); await writeAll(COLLECTIONS.SERIES,dataset.series); await writeAll(COLLECTIONS.RUNS,dataset.runs); await writeAll(COLLECTIONS.ISSUES,dataset.issues); await writeAll(COLLECTIONS.COLLECTIONS,dataset.collections,upsertCollectionEdition); return result;}
